import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, rev;
        long cap;
        int cst;

        Edge(int to, int rev, long cap, int cst) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cst = cst;
        }
    }

    static class MCF {
        int size;
        List<List<Edge>> adj;
        List<int[]> edges;

        long[] potential;
        int[] prev_node, prev_edge;

        MCF(int size) {
            this.size = size;
            adj = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                adj.add(new ArrayList<>());
            }
            edges = new ArrayList<>();
        }

        int add_edge(int u, int v, long cap, int cst) {
            int index = edges.size();
            edges.add(new int[]{u, adj.get(u).size()});
            adj.get(u).add(new Edge(v, adj.get(v).size(), cap, cst));
            adj.get(v).add(new Edge(u, adj.get(u).size() - 1, 0, -cst));
            return index;
        }

        Edge get_edge(int i) {
            int u = edges.get(i)[0];
            int idx = edges.get(i)[1];
            Edge e = adj.get(u).get(idx);
            Edge re = adj.get(e.to).get(e.rev);
            return new Edge(u, e.to, e.cap + re.cap, e.cst);
        }

        List<Edge> all_edges() {
            List<Edge> res = new ArrayList<>();
            for (int i = 0; i < edges.size(); i++) {
                int u = edges.get(i)[0];
                int idx = edges.get(i)[1];
                Edge e = adj.get(u).get(idx);
                Edge re = adj.get(e.to).get(e.rev);
                res.add(new Edge(u, e.to, e.cap + re.cap, e.cst));
            }
            return res;
        }

        boolean dijkstra(int s, int t, int[] prev_node, int[] prev_edge, long[] dist, boolean[] visited) {
            Arrays.fill(dist, Long.MAX_VALUE);
            Arrays.fill(prev_node, -1);
            Arrays.fill(prev_edge, -1);
            Arrays.fill(visited, false);
            PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            dist[s] = 0;
            heap.offer(new long[]{0, s});
            while (!heap.isEmpty()) {
                long[] cur = heap.poll();
                long d = cur[0];
                int v = (int) cur[1];
                if (visited[v]) continue;
                visited[v] = true;
                if (v == t) break;
                for (int i = 0; i < adj.get(v).size(); i++) {
                    Edge e = adj.get(v).get(i);
                    if (visited[e.to] || e.cap == 0) continue;
                    long nd = d + e.cst;
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        prev_node[e.to] = v;
                        prev_edge[e.to] = i;
                        heap.offer(new long[]{nd, e.to});
                    }
                }
            }
            return visited[t];
        }

        List<long[]> min_cost_flow(int s, int t, long max_flow) {
            long flow = 0;
            long total_cost = 0;
            List<long[]> results = new ArrayList<>();
            results.add(new long[]{flow, total_cost});
            potential = new long[size];
            prev_node = new int[size];
            prev_edge = new int[size];
            long[] dist = new long[size];
            boolean[] visited = new boolean[size];

            while (flow < max_flow) {
                if (!dijkstra(s, t, prev_node, prev_edge, dist, visited))
                    break;
                long c = max_flow - flow;
                int v = t;
                while (v != s) {
                    int u = prev_node[v];
                    Edge e = adj.get(u).get(prev_edge[v]);
                    c = Math.min(c, e.cap);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = prev_node[v];
                    Edge e = adj.get(u).get(prev_edge[v]);
                    e.cap -= c;
                    adj.get(e.to).get(e.rev).cap += c;
                    v = u;
                }
                long delta = -potential[s];
                flow += c;
                total_cost += c * delta;
                if (results.get(results.size() - 1)[1] == total_cost)
                    results.remove(results.size() - 1);
                results.add(new long[]{flow, total_cost});
            }
            return results;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().split(" ");
        int n = Integer.parseInt(data[0]);
        data = br.readLine().split(" ");
        int a1 = Integer.parseInt(data[0]);
        int a2 = Integer.parseInt(data[1]);
        int a3 = Integer.parseInt(data[2]);
        data = br.readLine().split(" ");
        int b1 = Integer.parseInt(data[0]);
        int b2 = Integer.parseInt(data[1]);
        int b3 = Integer.parseInt(data[2]);

        MCF g = new MCF(8);
        g.add_edge(0, 1, a1, 0);
        g.add_edge(0, 2, a2, 0);
        g.add_edge(0, 3, a3, 0);
        g.add_edge(4, 7, b1, 0);
        g.add_edge(5, 7, b2, 0);
        g.add_edge(6, 7, b3, 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cst = ((j - i) % 3 == 1) ? 1 : 0;
                g.add_edge(i, j, Long.MAX_VALUE, cst);
            }
        }

        List<long[]> res = g.min_cost_flow(0, 7, (1L << 32) - 1);
        long ans1 = res.get(res.size() - 1)[0];
        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}
